"""Starter templates generated by `opsflow init`."""

from __future__ import annotations

from .config import OpsContext
from .storage import now_iso


def template_project_json(ctx: OpsContext) -> dict:
    return {
        "schema_version": 1,
        "summary": f"Baseline and active constraints for {ctx.project_name}.",
        "baseline": [
            "Record the current official baseline, entrypoints, and verified scope here."
        ],
        "constraints": [
            "Keep evaluation evidence separated by layer; never treat proxy metrics as production proof.",
            "Distinguish record timestamps, file observation time, and live process verification.",
        ],
        "evidence_refs": [],
        "updated_at": now_iso(ctx.default_timezone()),
    }


def template_ops_readme(ctx: OpsContext) -> str:
    ledger_lines = "\n".join(
        f"- `{name}`: `{path.relative_to(ctx.ops_dir).as_posix() if path.is_relative_to(ctx.ops_dir) else path}`"
        for name, path in ctx.all_ledger_paths().items()
    )
    return f"""# {ctx.project_name} Ops

Opsflow keeps long-running project state resumable with strict output budgets.
Read the brief first, inspect one track's context, query summaries, and expand
only the fields you need.

## Read First

```bash
opsflow brief
opsflow context --track <track_id>
opsflow query --keyword <topic> --offset 0
opsflow show <key> --field /metrics
```

Default UTF-8 byte budgets: `brief` 12 KiB, `context` 24 KiB, `query` 8 KiB, `show` 16 KiB.

## Layout

- `project.json`: official baseline, project-level constraints, and authoritative refs
- `BRIEF.md`: generated overview (`opsflow brief --write`); do not append by hand
- `tracks/<track_id>/track.json`: one overwrite-in-place state card per workstream (with `revision`)
- `lessons/`: concise reusable rules (total <= 64 KiB)
- `templates/`: starter track card and recurring monitor prompt templates
- `.index/`: rebuildable local SQLite search index (gitignored; never the source of truth)

### Ledgers

{ledger_lines}

## Update & Close

```bash
opsflow track set --file <track.json>
opsflow track set --file <update.json> --expected-revision <rev>
opsflow add-trace --track <track_id> --stage build --kind decision --status completed --title "..." --summary "..."
opsflow add-result --file <result.json>
opsflow track close <track_id> --conclusion "..." --expected-revision <rev>
opsflow brief --write
opsflow check
```
"""


